        public void ApplyEditPermission()
        {
            bool canEdit = EmployeeV2TabCanEdit.CanEdit(Session);
            if (btnSaveModal != null)
                btnSaveModal.Visible = canEdit;
            RefreshFileButtons(canEdit);
        }

        protected void fileUpload_UploadedComplete(object sender, AjaxControlToolkit.AsyncFileUploadEventArgs e)
        {
            Session[GetUploadSessionKey()] = null;

            if (!fileUpload.HasFile)
                return;

            long employeeId = GetEmployeeId();
            if (employeeId <= 0)
                return;

            string strFileName = fileUpload.FileName.Replace(" ", "-");
            if (strFileName.Length < 4)
                return;

            string strType = strFileName.Substring(strFileName.Length - 3).ToLower();
            if (strType == "exe" || strType == "dll" || strType == "bat" || strType == "cgi"
                || strType == "com" || strType == "msi" || strType == "ashx" || strType == "asmx" || strType == "aspx")
                return;

            string folder = GetEmployeeFolder(employeeId);
            if (string.IsNullOrEmpty(folder))
                return;

            Directory.CreateDirectory(folder);
            strFileName = string.Format("{0}_{1}_{2}",
                employeeId.ToString(CultureInfo.InvariantCulture),
                DateTime.Now.ToString("yyyyMMddHHmmss", CultureInfo.InvariantCulture),
                strFileName);
            fileUpload.SaveAs(Path.Combine(folder, strFileName));
            Session[GetUploadSessionKey()] = BuildRelativeLink(employeeId, strFileName);
        }

        protected void lbtPostFile_Click(object sender, EventArgs e)
        {
            object uploaded = Session[GetUploadSessionKey()];
            if (uploaded != null)
            {
                txtContentFile.Text = uploaded.ToString();
                RefreshFileButtons(EmployeeV2TabCanEdit.CanEdit(Session));
            }
            ScheduleOpenModalAfterUpdate();
            if (udpFile != null)
                udpFile.Update();
            udpAll.Update();
        }

        protected void lbtlDeleteFile_Click(object sender, EventArgs e)
        {
            long employeeId = GetEmployeeId();
            string currentLink = NormalizeLink(txtContentFile.Text);
            string originalLink = GetOriginalLink();
            if (!string.IsNullOrEmpty(currentLink)
                && !string.Equals(currentLink, originalLink, StringComparison.OrdinalIgnoreCase))
            {
                DeleteTaskFile(employeeId, currentLink);
            }

            txtContentFile.Text = string.Empty;
            Session[GetUploadSessionKey()] = null;
            RefreshFileButtons(EmployeeV2TabCanEdit.CanEdit(Session));
            ScheduleOpenModalAfterUpdate();
            if (udpFile != null)
                udpFile.Update();
            udpAll.Update();
        }

        protected void lbtViewFile_Click(object sender, EventArgs e)
        {
            string url = BuildFileUrl(NormalizeLink(txtContentFile.Text));
            if (!string.IsNullOrEmpty(url))
            {
                ScriptManager.RegisterStartupScript(this, this.GetType(), "EmpV2CongTacViewFile",
                    string.Format("window.open('{0}','_blank');", HttpUtility.JavaScriptStringEncode(url)), true);
            }
            ScheduleOpenModalAfterUpdate();
            udpAll.Update();
        }

