        private void BindFileField(string link, bool clearSession)
        {
            string normalized = NormalizeLink(link);
            txtContentFile.Text = normalized ?? string.Empty;
            ViewState["EmpV2_CongTacEdit_OriginalLink"] = normalized;
            if (clearSession)
                Session[GetUploadSessionKey()] = null;
            RefreshFileButtons(EmployeeV2TabCanEdit.CanEdit(Session));
        }

        private void RefreshFileButtons(bool canEdit)
        {
            bool hasFile = txtContentFile != null && !string.IsNullOrWhiteSpace(txtContentFile.Text);
            if (fileUpload != null)
                fileUpload.Visible = canEdit;
            if (lbtlDeleteFile != null)
                lbtlDeleteFile.Visible = canEdit && hasFile;
            if (lbtViewFile != null)
                lbtViewFile.Visible = hasFile;
        }

        private string GetOriginalLink()
        {
            object o = ViewState["EmpV2_CongTacEdit_OriginalLink"];
            if (o == null)
                return string.Empty;
            return NormalizeLink(o.ToString()) ?? string.Empty;
        }

        private static string NormalizeLink(string link)
        {
            if (string.IsNullOrWhiteSpace(link))
                return null;
            return link.Replace('\\', '/').Trim();
        }

        private string GetUploadSessionKey()
        {
            return "fileUpload" + this.ClientID;
        }

        private static string GetUploadRoot()
        {
            string root = DCore.Globals.GetConfig("PhysicalDirectory_Upload");
            if (string.IsNullOrEmpty(root))
                return string.Empty;
            return Path.Combine(root, "Data", "HRS_Task");
        }

        private static string GetEmployeeFolder(long employeeId)
        {
            if (employeeId <= 0)
                return string.Empty;
            return Path.Combine(GetUploadRoot(), employeeId.ToString(CultureInfo.InvariantCulture));
        }

        private static string BuildRelativeLink(long employeeId, string fileName)
        {
            if (employeeId <= 0 || string.IsNullOrEmpty(fileName))
                return string.Empty;
            return employeeId.ToString(CultureInfo.InvariantCulture) + "/" + fileName;
        }

        public static string BuildFileUrl(string relativePath)
        {
            string baseUrl = DCore.Globals.GetConfig("LogicalDirectory_Upload");
            if (string.IsNullOrEmpty(baseUrl) || string.IsNullOrEmpty(relativePath))
                return string.Empty;

            string[] parts = relativePath.Replace('\\', '/').Split(new char[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
            StringBuilder sb = new StringBuilder();
            sb.Append(baseUrl.TrimEnd('/'));
            sb.Append("/Data/HRS_Task");
            int i;
            for (i = 0; i < parts.Length; i++)
            {
                sb.Append('/');
                sb.Append(Uri.EscapeDataString(parts[i]));
            }
            return sb.ToString();
        }

        private static void DeleteOldFileIfReplaced(long employeeId, string oldLink, string newLink)
        {
            if (string.IsNullOrEmpty(oldLink))
                return;
            if (string.Equals(oldLink, newLink, StringComparison.OrdinalIgnoreCase))
                return;
            DeleteTaskFile(employeeId, oldLink);
        }

        private static void DeleteTaskFile(long employeeId, string relativePath)
        {
            if (employeeId <= 0 || string.IsNullOrWhiteSpace(relativePath))
                return;

            string normalized = relativePath.Replace('\\', '/').Trim('/');
            if (normalized.IndexOf("..", StringComparison.Ordinal) >= 0)
                return;

            string prefix = employeeId.ToString(CultureInfo.InvariantCulture) + "/";
            if (normalized.IndexOf(prefix, StringComparison.OrdinalIgnoreCase) != 0)
                return;

            string physical = Path.Combine(GetUploadRoot(), normalized.Replace('/', Path.DirectorySeparatorChar));
            if (File.Exists(physical))
                File.Delete(physical);
        }

