private bool TrySavePostedFile(long employeeId, HttpPostedFile postedFile, out string relativeLink, out string errorMessage)
{
    relativeLink = null;
    errorMessage = null;

    if (employeeId <= 0)
    {
        errorMessage = "Không xác định được nhân viên để lưu tập tin.";
        return false;
    }
    if (postedFile == null || postedFile.ContentLength <= 0)
    {
        errorMessage = "Tập tin rỗng hoặc không đọc được.";
        return false;
    }

    string originalName = Path.GetFileName(postedFile.FileName);
    if (string.IsNullOrWhiteSpace(originalName))
    {
        errorMessage = "Tên tập tin không hợp lệ.";
        return false;
    }

    originalName = originalName.Replace(" ", "-");
    string ext = Path.GetExtension(originalName);
    if (string.IsNullOrEmpty(ext) || ext.Length < 2)
    {
        errorMessage = "Tập tin phải có phần mở rộng (vd: .pdf, .docx).";
        return false;
    }

    if (IsBlockedUploadExtension(ext))
    {
        errorMessage = "Không được phép tải lên loại tập tin này.";
        return false;
    }

    string folder = GetEmployeeFolder(employeeId);
    if (string.IsNullOrEmpty(folder))
    {
        errorMessage = "Chưa cấu hình thư mục upload (PhysicalDirectory_Upload).";
        return false;
    }

    string storedName = string.Format("{0}_{1}_{2}",
        employeeId.ToString(CultureInfo.InvariantCulture),
        DateTime.Now.ToString("yyyyMMddHHmmss", CultureInfo.InvariantCulture),
        originalName);

    Directory.CreateDirectory(folder);
    string physicalPath = Path.Combine(folder, storedName);
    postedFile.SaveAs(physicalPath);
    relativeLink = BuildRelativeLink(employeeId, storedName);
    return true;
}

private static bool IsBlockedUploadExtension(string ext)
{
    if (string.IsNullOrEmpty(ext))
        return true;
    string e = ext.ToLower(CultureInfo.InvariantCulture).TrimStart('.');
    return e == "exe" || e == "dll" || e == "bat" || e == "cgi" || e == "com"
        || e == "msi" || e == "ashx" || e == "asmx" || e == "aspx";
}

