private HttpPostedFile GetTaskPostedFile()
{
    if (fuTaskFile != null && fuTaskFile.HasFile && fuTaskFile.PostedFile != null && fuTaskFile.PostedFile.ContentLength > 0)
        return fuTaskFile.PostedFile;

    if (fuTaskFile == null || Request == null || Request.Files == null || Request.Files.Count == 0)
        return null;

    HttpPostedFile byUnique = Request.Files[fuTaskFile.UniqueID];
    if (byUnique != null && byUnique.ContentLength > 0)
        return byUnique;

    string controlId = fuTaskFile.ID;
    for (int i = 0; i < Request.Files.Count; i++)
    {
        string key = Request.Files.GetKey(i);
        if (string.IsNullOrEmpty(key))
            continue;
        if (key.IndexOf(controlId, StringComparison.OrdinalIgnoreCase) < 0)
            continue;
        HttpPostedFile candidate = Request.Files[i];
        if (candidate != null && candidate.ContentLength > 0)
            return candidate;
    }

    return null;
}

