private void RegisterSaveButtonPostBackOnAncestorUpdatePanels()
{
    if (btnSaveModal == null)
        return;

    Control current = btnSaveModal.Parent;
    while (current != null)
    {
        UpdatePanel panel = current as UpdatePanel;
        if (panel != null)
            AddPostBackTriggerIfMissing(panel, btnSaveModal);
        current = current.Parent;
    }
}

private static void AddPostBackTriggerIfMissing(UpdatePanel panel, Control triggerControl)
{
    if (panel == null || triggerControl == null)
        return;

    UpdatePanel triggerPanel = GetUpdatePanelParent(triggerControl);
    string controlId = triggerControl.ID;
    if (triggerPanel != panel)
        controlId = triggerControl.UniqueID;

    foreach (UpdatePanelTrigger existing in panel.Triggers)
    {
        PostBackTrigger pbt = existing as PostBackTrigger;
        if (pbt == null)
            continue;
        if (string.Equals(pbt.ControlID, controlId, StringComparison.OrdinalIgnoreCase)
            || string.Equals(pbt.ControlID, triggerControl.ID, StringComparison.OrdinalIgnoreCase)
            || string.Equals(pbt.ControlID, triggerControl.UniqueID, StringComparison.OrdinalIgnoreCase))
            return;
    }

    PostBackTrigger trigger = new PostBackTrigger();
    trigger.ControlID = controlId;
    panel.Triggers.Add(trigger);
}

private static UpdatePanel GetUpdatePanelParent(Control control)
{
    Control current = control != null ? control.Parent : null;
    while (current != null)
    {
        UpdatePanel panel = current as UpdatePanel;
        if (panel != null)
            return panel;
        current = current.Parent;
    }
    return null;
}

