using System;
using System.IO;
using System.Web;
using System.Web.SessionState;
using InformationWeb.Controls.Employee_V2;

namespace InformationWeb
{
    /// <summary>
    /// Tải file đính kèm HRS_Task (FTP HRS_Task_Files) — dùng từ lưới tab Công tác.
    /// </summary>
    public class DownloadHrsTaskFile : IHttpHandler, IReadOnlySessionState
    {
        public void ProcessRequest(HttpContext context)
        {
            if (WebGlobal.User == null)
            {
                context.Response.Write("Bạn chưa đăng nhập hệ thống!");
                return;
            }

            string keyParam = context.Request["key"];
            if (string.IsNullOrEmpty(keyParam))
            {
                context.Response.Write("Sai tham số tập tin!");
                return;
            }

            string decoded;
            try
            {
                decoded = WebGlobal.DecodeRequest(keyParam);
            }
            catch (Exception)
            {
                context.Response.Write("Tham số không hợp lệ!");
                return;
            }

            if (string.IsNullOrEmpty(decoded))
            {
                context.Response.Write("Tham số không hợp lệ!");
                return;
            }

            string[] parts = decoded.Split('|');
            if (parts.Length < 2)
            {
                context.Response.Write("Tham số không đúng định dạng!");
                return;
            }

            string linkFileName = parts[0];
            string userName = parts[1];
            if (string.IsNullOrEmpty(linkFileName)
                || string.IsNullOrEmpty(userName)
                || !string.Equals(userName, WebGlobal.User.UserName, StringComparison.OrdinalIgnoreCase))
            {
                context.Response.Write("Bạn không có quyền truy cập tập tin này!");
                return;
            }

            string localPath = TabCongTacEdit.DownloadTaskFileToLocal(context.Server, linkFileName);
            if (string.IsNullOrEmpty(localPath) || !File.Exists(localPath))
            {
                context.Response.Write("Tập tin không còn khả dụng!");
                return;
            }

            string downloadName = DownloadFile.FilterFileName(Path.GetFileName(linkFileName));
            if (string.IsNullOrEmpty(downloadName))
                downloadName = Path.GetFileName(linkFileName);

            HttpResponse response = context.Response;
            response.ClearContent();
            response.Clear();
            response.ContentType = "application/octet-stream";
            response.AddHeader("Content-Disposition", "attachment; filename=" + downloadName + ";");
            response.TransmitFile(localPath);
            response.Flush();
            response.End();
        }

        public bool IsReusable
        {
            get { return false; }
        }
    }
}

