        return;
    }

    long taskId = GetCurrentTaskId();
    if (taskId <= 0)
    {
        MsgBox.ShowWarning("Chưa có mã công tác để xóa tập tin.");
        ScheduleOpenModalAfterUpdate();
        udpAll.Update();
        return;
    }

    string link = GetStoredLink();
    if (string.IsNullOrWhiteSpace(link))
    {
        ApplyAttachmentUi();
        ScheduleOpenModalAfterUpdate();
        udpAll.Update();
        return;
    }

    if (!FtpDeleteTaskFile(link))
    {
        MsgBox.ShowWarning("Không xóa được tập tin trên máy chủ.");
        ScheduleOpenModalAfterUpdate();
        udpAll.Update();
        return;
    }

    SessionUser objUser = Session[Globals.USER] as SessionUser;
    if (objUser == null)
    {
        MsgBox.ShowWarning("Phiên làm việc đã hết. Vui lòng đăng nhập lại.");
        return;
    }

    HRS_Task item = new HRS_Task();
