    {
        MsgBox.ShowWarning("Không lấy được thông tin công tác.");
        ScheduleOpenModalAfterUpdate();
        udpAll.Update();
        return;
    }

    item.BeginTransaction();
    try
    {
        item.Link = null;
        item.UpdatedUser = objUser.UserName.ToLower();
        if (!item.Update())
        {
            try { item.RollBackTransaction(); }
            catch { }
            MsgBox.ShowWarning("Không cập nhật được hồ sơ sau khi xóa tập tin.");
            ScheduleOpenModalAfterUpdate();
            udpAll.Update();
            return;
        }

        item.CommitTransaction();
    }
    catch (Exception ex)
    {
        System.Diagnostics.Debug.WriteLine("TabCongTacEdit.DeleteFile: " + ex.Message);
        try { item.RollBackTransaction(); }
        catch { }
        MsgBox.ShowError("Lỗi khi xóa tập tin đính kèm.");
        ScheduleOpenModalAfterUpdate();
        udpAll.Update();
        return;
    }

    SetStoredLink(string.Empty);
    hidClearLink.Value = string.Empty;
    ApplyAttachmentUi();
    ScheduleOpenModalAfterUpdate();
    udpAll.Update();
    MsgBox.ShowInfo("Đã xóa tập tin đính kèm.");

