            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabCongTacEdit.DeleteTempFileSafe: " + ex.Message);
            }
        }

        private static bool FtpUploadTaskFile(string localPath, string remoteFileName)
        {
            if (string.IsNullOrWhiteSpace(localPath) || string.IsNullOrWhiteSpace(remoteFileName))
                return false;

            try
            {
                FTPLib objFtp = new FTPLib();
                return objFtp.UploadLargeFile(localPath, FtpTaskFolder, remoteFileName);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabCongTacEdit.FtpUploadTaskFile: " + ex.Message);
                return false;
            }
        }

        private static bool FtpDeleteTaskFile(string remoteFileName)
        {
            if (string.IsNullOrWhiteSpace(remoteFileName))
                return true;

            try
            {
                string ftpPath = Path.Combine(FtpTaskFolder, remoteFileName.Trim());
                FTPLib objFtp = new FTPLib();
                return objFtp.Delete(ftpPath);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabCongTacEdit.FtpDeleteTaskFile: " + ex.Message);
                return false;
            }
        }

        private string FtpDownloadTaskFile(string remoteFileName)
        {
            return DownloadTaskFileToLocal(Server, remoteFileName);
        }

        /// <summary>
        /// URL tải file đính kèm công tác (lưới tab Công tác).
        /// </summary>
        public static string BuildFileUrl(string linkFileName)
        {
            if (string.IsNullOrWhiteSpace(linkFileName))
                return string.Empty;

            HttpContext context = HttpContext.Current;
            if (context == null || context.Session == null)
                return string.Empty;

            SessionUser sessionUser = context.Session[Globals.USER] as SessionUser;
            if (sessionUser == null || string.IsNullOrEmpty(sessionUser.UserName))
                return string.Empty;

            string token = WebGlobal.EncodeRequest(linkFileName.Trim() + "|" + sessionUser.UserName.ToLower());
            if (string.IsNullOrEmpty(token))
                return string.Empty;

            string relativePath = "~/DownloadHrsTaskFile.ashx?key=" + HttpUtility.UrlEncode(token);
            Page page = context.Handler as Page;
            if (page != null)
                return page.ResolveUrl(relativePath);

            return VirtualPathUtility.ToAbsolute(relativePath);
        }

        public static string DownloadTaskFileToLocal(HttpServerUtility server, string remoteFileName)
        {
            if (server == null || string.IsNullOrWhiteSpace(remoteFileName))
                return null;

            try
            {
                string ftpPath = Path.Combine(FtpTaskFolder, remoteFileName.Trim());
                string localDir = server.MapPath("~/Temp/FTPFile/" + FtpTaskFolder);
                if (!Directory.Exists(localDir))
                    Directory.CreateDirectory(localDir);

                FTPLib objFtp = new FTPLib();
                return objFtp.Download(ftpPath, localDir);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabCongTacEdit.DownloadTaskFileToLocal: " + ex.Message);
                return null;
            }
        }
    }
