            if (string.IsNullOrEmpty(tempPath))
                return false;

            try
            {
                string newLink = item.Link ?? string.Empty;
                if (!string.IsNullOrWhiteSpace(existingLink)
                    && !string.Equals(existingLink.Trim(), newLink, StringComparison.OrdinalIgnoreCase))
                    FtpDelete(existingLink.Trim());

                return FtpUpload(tempPath, newLink);
            }
            finally
            {
