            }
        }

        private bool UpdateTaskLink(long taskId, string link, string userName)
        {
            HRS_Task item = new HRS_Task();
            item.TaskID = taskId;
            if (!item.Get())
                return false;

            item.BeginTransaction();
            try
            {
                item.Link = link;
                item.UpdatedUser = userName;
                if (!item.Update())
                {
                    item.RollBackTransaction();
                    return false;
                }
                item.CommitTransaction();
                return true;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabCongTacEdit.UpdateTaskLink: " + ex.Message);
                try { item.RollBackTransaction(); }
                catch { }
                return false;
            }
        }

        private void RegisterFileUploadPostBackTriggers()
        {
            UpdatePanel panel = GetParentUpdatePanel(this);
            if (panel == null)
                return;

            AddPostBackTriggerIfMissing(panel, btnSaveModal);
            AddPostBackTriggerIfMissing(panel, lbtViewFile);
            AddPostBackTriggerIfMissing(panel, lbtlDeleteFile);
        }

        private static UpdatePanel GetParentUpdatePanel(Control control)
        {
            for (Control c = control != null ? control.Parent : null; c != null; c = c.Parent)
            {
                UpdatePanel panel = c as UpdatePanel;
                if (panel != null)
                    return panel;
            }
            return null;
        }

        private static void AddPostBackTriggerIfMissing(UpdatePanel panel, Control control)
        {
            if (panel == null || control == null || string.IsNullOrEmpty(control.ID))
                return;

            foreach (UpdatePanelTrigger trigger in panel.Triggers)
            {
                PostBackTrigger pbt = trigger as PostBackTrigger;
                if (pbt != null && pbt.ControlID == control.ID)
                    return;
            }
            panel.Triggers.Add(new PostBackTrigger { ControlID = control.ID });
        }

