namespace InformationWeb
{
    /// <summary>Handler tải file HRS_Task — logic FTP nằm tại TabCongTacEdit.</summary>
    public class DownloadHrsTaskFile : IHttpHandler, IReadOnlySessionState
    {
        public void ProcessRequest(HttpContext context)
        {
            if (WebGlobal.User == null)
            {
                context.Response.Write("Bạn chưa đăng nhập hệ thống!");
                return;
            }

            string key = context.Request["key"];
            if (string.IsNullOrEmpty(key))
            {
                context.Response.Write("Sai tham số tập tin!");
                return;
            }

            string decoded;
            try { decoded = WebGlobal.DecodeRequest(key); }
            catch { decoded = null; }

            string[] parts = string.IsNullOrEmpty(decoded) ? null : decoded.Split('|');
            if (parts == null || parts.Length < 2
                || string.IsNullOrEmpty(parts[0])
                || !string.Equals(parts[1], WebGlobal.User.UserName, StringComparison.OrdinalIgnoreCase))
            {
                context.Response.Write("Bạn không có quyền truy cập tập tin này!");
                return;
            }

            string localPath = Controls.Employee_V2.TabCongTacEdit.DownloadTaskFileToLocal(context.Server, parts[0]);
            if (string.IsNullOrEmpty(localPath) || !File.Exists(localPath))
            {
                context.Response.Write("Tập tin không còn khả dụng!");
                return;
            }

            string name = DownloadFile.FilterFileName(Path.GetFileName(parts[0]));
            if (string.IsNullOrEmpty(name))
                name = Path.GetFileName(parts[0]);

            HttpResponse response = context.Response;
            response.Clear();
            response.ContentType = "application/octet-stream";
            response.AddHeader("Content-Disposition", "attachment; filename=" + name + ";");
            response.TransmitFile(localPath);
            response.Flush();
            response.End();
        }

        public bool IsReusable { get { return false; } }
    }
}
